/** A personal (user-scoped) credential — a BYO AI provider config a user sets
 *  up once and routes to chosen workspaces. See migration 053. */
export interface UserCredentialsTable {
  id: Generated<string>;
  user_id: string;
  kind: Generated<string>; // 'ai-provider'
  provider_id: string; // 'ollama' | 'openai' | 'anthropic' | 'edge-bridge' | …
  label: Generated<string>;
  credentials_encrypted: string; // AES-256-GCM (global key), JSON object
  route_mode: Generated<"my-calls" | "workspace-default">;
  route_scope: Generated<"sole_member" | "owner" | "all_mine" | "explicit">;
  auto_enable_new: Generated<boolean>;
  /** What the save's probe said about the key (connection-verification.ts). */
  verification: Generated<Record<string, unknown> | null>;
  /** What the platform made this connection from, when a heal made it on
   *  someone's behalf ("digifab_detectors:<id>"): making it again returns
   *  this one. Null for a connection a person made. (20260929-157) */
  origin_key: Generated<string | null>;
  created_at: Generated<Date>;
  updated_at: Generated<Date>;
}

/** Explicit-scope routing: which workspaces an 'explicit'-scoped personal
 *  credential reaches, plus the PER-WORKSPACE mode (Just me vs Share with
 *  members). Row present = routed to this org; absent = Off. */
/** A person's own default AI per job (20261008-207, #5404): the steps to ask
 *  in order, position 0 first, each one of their own AI connections and a
 *  model. Every workspace they use follows these unless it chose for the job
 *  itself. */
/** Who reads a workspace's personal documents (#5621). No row = on this
 *  machine only. */
export interface OrgPersonalDocumentsReaderTable {
  org_id: string;
  /** A personal connection's id, or `workspace:<provider id>`. */
  connection: string;
  provider_id: string;
  consented_by: string | null;
  consented_at: Generated<Date>;
  consent_text: string;
}

export interface UserAiJobDefaultsTable {
  user_id: string;
  /** A job of AI_DEFAULT_JOBS; 'photos' rows are kept only for an api from
   *  before Quick look and Thorough reading split it (migration 210). */
  job: import("@cobblr/platform-contract").AiDefaultJobId | "photos";
  position: number;
  credential_id: string;
  /** Always a model the provider serves; with `model_follows`, what that
   *  latest meant when it was saved. */
  model: string;
  /** A family's latest when one was picked (claude-haiku-latest). */
  model_follows: string | null;
  created_at: Generated<Date>;
  updated_at: Generated<Date>;
}

export interface UserCredentialOrgsTable {
  /** Surrogate key (20260928-144): a connection has a general row and one row
   *  per job it is ordered for, in the same workspace. */
  id: Generated<string>;
  credential_id: string;
  org_id: string;
  mode: Generated<"my-calls" | "workspace-default">;
  /** For a 'workspace-default' offer: when the workspace owner approved it
   *  (null = a pending offer). 'my-calls' routes ignore this. */
  approved_at: Date | null;
  approved_by: string | null;
  /** The one approved workspace-default AI the owner chose as the workspace
   *  default (at most one active per org). */
  active: Generated<boolean>;
  /** Where this connection sits in the workspace's order (1 first). Null =
   *  unranked: it sorts after everything ranked and falls back to recency,
   *  which is how every route behaved before ranking existed. (20260821-107) */
  rank: number | null;
  /** Which capability this ranking is for — "chat", "identify", … Null = the
   *  workspace's general order, used by any capability with no order of its
   *  own. One model is rarely right for a live camera scan AND for chat. */
  capability: string | null;
}

