/** Where a piece of feedback came from. Every value must name a way back to
 *  the reporter in `reporterReplyRoute` — adding one here fails to compile
 *  there until it does. */
import type { DeliveryOutcomes } from "@cobblr/platform-contract/delivery-outcome";

export type FeedbackOrigin = "in-app" | "discord" | "discord-dm";

export interface FeedbackTable {
  id: Generated<string>;
  // Null for a discord-origin ticket (no platform user — see origin_ref).
  user_id: string | null;
  org_id: string | null;
  type: Generated<string>;
  message: string;
  context: Generated<Record<string, unknown>>;
  status: Generated<string>;
  admin_notes: string | null;
  // Where it came from + how to reply (20260609-051). 'in-app' → notification +
  // email; 'discord' → the support bot posts into origin_ref.thread_id;
  // 'discord-dm' → a new item created straight from a bot DM (routes by intent).
  origin: Generated<FeedbackOrigin>;
  /** Per-channel outcome of the LAST reply we sent (20260821-106). Null for an
   *  item nobody has replied to, or one replied to before the column existed. */
  reply_delivery: DeliveryOutcomes | null;
  /** The public changelog line a resolve left for the owner to publish (20261019-236). */
  held_summary: string | null;
  /** The reporter message a resolve by an API token held back: `message` null = the default line. */
  held_reply: { message: string | null; status: "resolved" | "wontfix" } | null;
  /** When the owner published the held summary and reply; null = not yet. */
  published_at: Date | null;
  /** Can anyone be reached about this item (20261004-197)? False for an
   *  anonymous sandbox guest with no contact address. Decided where the item is
   *  written (feedback-reachability.ts); every surface reads it. */
  reachable: Generated<boolean>;
  unreachable_reason: string | null;
  /** An address a sandbox visitor chose to leave, and when they agreed. */
  contact_email: string | null;
  contact_consented_at: Date | null;
  origin_ref: {
    channel_id: string;
    thread_id: string;
    message_id?: string;
    user_id?: string;
    username?: string;
  } | null;
  // Conversation follow-ups (20260609-052). The original report is `message`;
  // each reporter reply in the ticket thread appends here. Re-triage reads both.
  followups: Generated<
    // `role` distinguishes the two sides of the conversation in the in-app
    // thread (and the Discord round-trip). Optional for back-compat: older
    // entries (Discord #support follow-ups) are all reporter-side ("user").
    Array<{ at: string; from: string; text: string; role?: "user" | "team"; images?: Array<{ url: string; name?: string }> }>
  >;
  // Reporter-attached screenshots (20260609-050). Refs into the reporter's
  // workspace core-files; bytes read cross-tenant for the super-admin view.
  attachments: Generated<Array<{ file_id: string; name?: string; content_type?: string }>>;
  // AI triage verdict (20260609-049). Null until the analyzer claims the row.
  triage_priority: "urgent" | "high" | "medium" | "low" | null;
  triage_valid: boolean | null;
  triage_viable: boolean | null;
  triage_summary: string | null;
  triage_action: string | null;
  triaged_at: Date | null;
  triage_model: string | null;
  // The Discord "New feedback" post (20260710-081) — captured when announce()
  // posts with ?wait=true, so the item's lifecycle stage (grabbed → building →
  // PR up → shipped) can be reflected back onto that same message as emoji
  // reactions by the support bot. Null when the announce is disabled/undelivered,
  // or the webhook targets a non-tracked channel.
  announce_message_id: string | null;
  announce_channel_id: string | null;
  // The workspace's name, kept when the workspace is deleted (org_id is then
  // null), so the operator's queue still says where the report came from.
  workspace_name: string | null;
  created_at: Generated<Date>;
  updated_at: Generated<Date>;
}

