/** When a channel is allowed to interrupt this person. Per (user, channel) —
 *  deliberately NOT per event type like the two tables above it, because the
 *  point is one message across every event. */
export interface NotificationDeliveryWindowsTable {
  user_id: string;
  channel: string;
  mode: "immediate" | "daily";
  /** Minutes past LOCAL midnight. */
  deliver_at_minute: Generated<number>;
  /** IANA zone. */
  timezone: Generated<string>;
  /** Idempotency for the sweeper: one flush per window per local day. */
  last_delivered_at: ColumnType<Date | null, Date | null | undefined, Date | null>;
  /** The cadence for DATED things (expiring today, service due) as opposed to
   *  things that just happened. `inherit` is what a single-cadence window
   *  always meant. */
  schedule_mode: Generated<"inherit" | "immediate" | "daily">;
  schedule_deliver_at_minute: Generated<number>;
  /** Its own stamp: the two windows open at different times of day. */
  schedule_last_delivered_at: ColumnType<Date | null, Date | null | undefined, Date | null>;
  updated_at: Generated<Date>;
}

/** The instance's VAPID key pair (one row): every browser subscription is
 *  bound to the public key, so it is made once and kept. */
export interface PushVapidKeysTable {
  id: Generated<number>;
  /** base64url of the uncompressed P-256 public point, as a browser takes it. */
  public_key: string;
  /** The private key's 32 bytes, base64url, encrypted with encryptCreds. */
  private_key_enc: string;
  /** "generated" on first boot, "operator" when given through the env. */
  source: Generated<string>;
  created_at: Generated<Date>;
}

